package com.knowflow.learning.actions;
import com.fasterxml.jackson.databind.*;
import com.knowflow.entity.*;
import com.knowflow.mapper.*;
import com.knowflow.dto.TaskDTO;
import com.knowflow.service.TaskService;
import com.knowflow.support.FakeAiConfiguration;
import com.knowflow.utils.JwtUtils;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.mock.mockito.SpyBean;
import org.springframework.context.annotation.Import;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.*;
import org.springframework.test.web.servlet.MockMvc;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("local") @Import(FakeAiConfiguration.class)
@TestPropertySource(properties={"knowflow.datasource.config-file=/tmp/knowflow-phase4e-plan-test-no-config.json","knowflow.datasource.type=h2","knowflow.datasource.h2.url=jdbc:h2:mem:phase4e_plans;DB_CLOSE_DELAY=-1;MODE=MySQL"})
class DailyLearningPlanHttpTest {
 @Autowired MockMvc http;@Autowired ObjectMapper json;@Autowired SysUserMapper users;@Autowired JwtUtils jwt;@Autowired JdbcTemplate sql;
 @Autowired DailyLearningPlanService plans;@SpyBean LearningActionDraftMapper draftRows;
 @Autowired DocCategoryMapper categories;@Autowired DocDocumentMapper docs;@Autowired KgEntityMapper knowledge;@Autowired KnowledgeMasteryMapper mastery;
 @SpyBean TaskService tasks;Long owner,other,admin;
 @BeforeEach void actors(){owner=user("USER");other=user("USER");admin=user("ADMIN");}
 Long user(String role){var u=new SysUser();u.setUsername("phase4e-"+UUID.randomUUID());u.setPassword("unused");u.setRole(role);users.insert(u);return u.getId();}
 Long doc(Long category){var d=new DocDocument();d.setTitle("phase4e-source");d.setContent("actual source");d.setStatus(1);d.setCategoryId(category);docs.insert(d);return d.getId();}
 String auth(Long user){return "Bearer "+jwt.generateToken(user,"phase4e","USER");}
 PlanModels.Request request(int minutes){var r=new PlanModels.Request();r.setAvailableMinutes(minutes);return r;}
 JsonNode preview(int minutes)throws Exception{return json.readTree(http.perform(post("/api/learning/action-plans/daily/preview").header("Authorization",auth(owner)).contentType("application/json").content(json.writeValueAsString(request(minutes)))).andExpect(status().isOk()).andReturn().getResponse().getContentAsString(java.nio.charset.StandardCharsets.UTF_8)).path("data");}
 PlanModels.ConfirmRequest confirmation(JsonNode d){var r=new PlanModels.ConfirmRequest();r.setVersion(d.path("version").asInt());r.setConfirmationToken(d.path("confirmationToken").asText());r.setIdempotencyKey("confirm_"+UUID.randomUUID().toString().replace("-",""));List<PlanModels.EditedItem> items=new ArrayList<>();for(var i:d.path("tasks"))items.add(new PlanModels.EditedItem(i.path("key").asText(),i.path("title").asText(),i.path("estimatedMinutes").asInt(),i.path("priority").asText()));r.setTasks(items);return r;}
 JsonNode confirm(JsonNode d,PlanModels.ConfirmRequest r)throws Exception{return json.readTree(http.perform(post("/api/learning/action-plans/"+d.path("planId").asText()+"/confirm").header("Authorization",auth(owner)).contentType("application/json").content(json.writeValueAsString(r))).andExpect(status().isOk()).andReturn().getResponse().getContentAsString(java.nio.charset.StandardCharsets.UTF_8)).path("data");}
 int count(){return sql.queryForObject("SELECT COUNT(*) FROM task WHERE user_id=? AND deleted=0",Integer.class,owner);}
 @Test void noHistoryProducesFoundationWithMissingWarningsAndNoTaskWrite()throws Exception{var d=preview(180);assertEquals("RULE",d.path("source").asText());assertTrue(d.path("warnings").toString().contains("缺少"));assertEquals(0,count());assertEquals(180,java.util.stream.StreamSupport.stream(d.path("tasks").spliterator(),false).mapToInt(i->i.path("estimatedMinutes").asInt()).sum());}
 @Test void requiresConfirmationTokenBeforeAnyWrite()throws Exception{var d=preview(90);var r=confirmation(d);r.setConfirmationToken("forged");http.perform(post("/api/learning/action-plans/"+d.path("planId").asText()+"/confirm").header("Authorization",auth(owner)).contentType("application/json").content(json.writeValueAsString(r))).andExpect(status().isForbidden()).andExpect(jsonPath("$.code").value(403));assertEquals(0,count());}
 @Test void duplicateConfirmationReturnsSameRealIds()throws Exception{var d=preview(90);var r=confirmation(d);var a=confirm(d,r);var b=confirm(d,r);assertEquals(a.path("createdTasks"),b.path("createdTasks"));assertEquals(d.path("tasks").size(),count());}
 @Test void concurrentConfirmationCreatesOneBatch()throws Exception{var d=preview(90);var r=confirmation(d);var executor=Executors.newFixedThreadPool(2);try{var futures=executor.<PlanModels.Draft>invokeAll(List.of(()->plans.confirm(owner,d.path("planId").asText(),r),()->plans.confirm(owner,d.path("planId").asText(),r)));assertEquals(futures.get(0).get().createdTasks(),futures.get(1).get().createdTasks());assertEquals(d.path("tasks").size(),count());}finally{executor.shutdownNow();}}
 @Test void batchFailureRollsBackEveryTaskAndLeavesPreview()throws Exception{var d=preview(120);var r=confirmation(d);AtomicInteger calls=new AtomicInteger();doAnswer(i->{if(calls.incrementAndGet()==2)throw new IllegalStateException("injected second task failure");return i.callRealMethod();}).when(tasks).createTask(eq(owner),any(TaskDTO.class));assertThrows(Exception.class,()->plans.confirm(owner,d.path("planId").asText(),r));assertEquals(0,count());assertEquals("PREVIEW",draftRows.selectById(d.path("planId").asText()).getState());}
 @Test void expiredDraftRejectsWithoutWriting()throws Exception{var d=preview(90);sql.update("UPDATE learning_action_draft SET expires_at=? WHERE id=?",java.sql.Timestamp.from(Instant.now().minusSeconds(1)),d.path("planId").asText());http.perform(post("/api/learning/action-plans/"+d.path("planId").asText()+"/confirm").header("Authorization",auth(owner)).contentType("application/json").content(json.writeValueAsString(confirmation(d)))).andExpect(status().isGone()).andExpect(jsonPath("$.code").value(410));assertEquals(0,count());}
 @Test void otherUserAndAdminCannotReadOrConfirmAnotherUsersDraft()throws Exception{var d=preview(90);for(Long actor:List.of(other,admin)){http.perform(get("/api/learning/action-plans/"+d.path("planId").asText()).header("Authorization",auth(actor))).andExpect(status().isNotFound());http.perform(post("/api/learning/action-plans/"+d.path("planId").asText()+"/confirm").header("Authorization",auth(actor)).contentType("application/json").content(json.writeValueAsString(confirmation(d)))).andExpect(status().isNotFound());}assertEquals(0,count());}
 @Test void editBudgetAndInventedCandidateAreRejected()throws Exception{var d=preview(20);var r=confirmation(d);r.setTasks(List.of(new PlanModels.EditedItem(d.path("tasks").get(0).path("key").asText(),"too much",21,"HIGH")));assertEquals(400,assertThrows(com.knowflow.exception.BusinessException.class,()->plans.confirm(owner,d.path("planId").asText(),r)).getCode());r.setTasks(List.of(new PlanModels.EditedItem("knowledge:999999","injected",1,"HIGH")));assertThrows(com.knowflow.exception.BusinessException.class,()->plans.confirm(owner,d.path("planId").asText(),r));assertEquals(0,count());}
 @Test void cancelledDraftCannotBeConfirmed()throws Exception{var d=preview(90);http.perform(delete("/api/learning/action-plans/"+d.path("planId").asText()).header("Authorization",auth(owner))).andExpect(status().isOk());assertThrows(com.knowflow.exception.BusinessException.class,()->plans.confirm(owner,d.path("planId").asText(),confirmation(d)));assertEquals(0,count());}
 @Test void actualDuePrivateKnowledgeUsedOnlyByOwnerAndRecheckedAtConfirmation()throws Exception{
  var category=new DocCategory();category.setName("private4e");category.setOwnerId(owner);category.setStatus(1);categories.insert(category);
  var k=new KgEntity();k.setName("Kafka真实证据");k.setDocId(doc(category.getId()));k.setCategoryId(category.getId());k.setType("CONCEPT");knowledge.insert(k);
  var m=new KnowledgeMastery();m.setUserId(owner);m.setKnowledgeId(k.getId());m.setConfidenceScore(50);m.setMasteryScore(20);m.setLearningStatus("WEAK");m.setLastLearnedAt(LocalDateTime.now());m.setNextReviewAt(LocalDateTime.now().minusDays(1));mastery.insert(m);
  var d=preview(90);assertEquals(k.getId().longValue(),d.path("tasks").get(0).path("resourceId").asLong());
  String body=http.perform(post("/api/learning/action-plans/context").header("Authorization",auth(other)).contentType("application/json").content("{}")).andExpect(status().isOk()).andReturn().getResponse().getContentAsString(java.nio.charset.StandardCharsets.UTF_8);assertFalse(body.contains("Kafka真实证据"));
  category.setOwnerId(other);categories.updateById(category);assertEquals(403,assertThrows(com.knowflow.exception.BusinessException.class,()->plans.confirm(owner,d.path("planId").asText(),confirmation(d))).getCode());assertEquals(0,count());
 }
 @Test void noEvidenceMasteryRecordIsNotLabeledWeak()throws Exception{var k=new KgEntity();k.setName("no-evidence4e");k.setDocId(doc(null));k.setType("CONCEPT");knowledge.insert(k);var m=new KnowledgeMastery();m.setUserId(owner);m.setKnowledgeId(k.getId());m.setMasteryScore(0);m.setConfidenceScore(0);m.setLearningStatus("WEAK");mastery.insert(m);assertFalse(preview(90).path("tasks").toString().contains("no-evidence4e"));}
 @Test void existingTaskSurvivesAppendAndLearningProjectionUsesSource()throws Exception{var dto=new TaskDTO();dto.setTitle("keep original");dto.setScheduledDate(LocalDate.now(ZoneId.of("Asia/Shanghai")));Long original=tasks.createTask(owner,dto);var d=preview(90);confirm(d,confirmation(d));assertEquals(d.path("tasks").size()+1,count());assertEquals("keep original",sql.queryForObject("SELECT title FROM task WHERE id=?",String.class,original));http.perform(get("/api/learning/tasks").header("Authorization",auth(owner))).andExpect(status().isOk()).andExpect(jsonPath("$.data[0].source").value("TASK"));}
 @Test void stateUpdateNeedsOwnershipAndConfirmation()throws Exception{var dto=new TaskDTO();dto.setTitle("Kafka复习");dto.setScheduledDate(LocalDate.now(ZoneId.of("Asia/Shanghai")));Long id=tasks.createTask(owner,dto);var d=plans.previewStatus(owner,id,"TASK",1,request(30));assertEquals(0,sql.queryForObject("SELECT status FROM task WHERE id=?",Integer.class,id));assertThrows(com.knowflow.exception.BusinessException.class,()->plans.previewStatus(other,id,"TASK",1,request(30)));var node=json.valueToTree(d);confirm(node,confirmation(node));assertEquals(1,sql.queryForObject("SELECT status FROM task WHERE id=?",Integer.class,id));}
 @Test void changedExistingTaskIsNotSilentlyOverwritten()throws Exception{var dto=new TaskDTO();dto.setTitle("original");dto.setScheduledDate(LocalDate.now(ZoneId.of("Asia/Shanghai")));Long id=tasks.createTask(owner,dto);var d=plans.previewChanges(owner,request(60));dto.setTitle("manual edit after preview");tasks.updateTask(owner,id,dto);var node=json.valueToTree(d);assertEquals(409,assertThrows(com.knowflow.exception.BusinessException.class,()->plans.confirm(owner,d.planId(),confirmation(node))).getCode());}
 @Test void anonymousCannotPreviewOrConfirm()throws Exception{http.perform(post("/api/learning/action-plans/daily/preview").contentType("application/json").content("{}")).andExpect(status().isUnauthorized());}
 @Test void regeneratedPlanRevokesOldVersionWithoutWritingTasks()throws Exception{var d=preview(90);var old=confirmation(d);var newer=plans.regenerate(owner,d.path("planId").asText(),request(120));assertEquals(d.path("planId").asText(),newer.planId());assertEquals(2,newer.version());assertEquals(409,assertThrows(com.knowflow.exception.BusinessException.class,()->plans.confirm(owner,newer.planId(),old)).getCode());assertEquals(0,count());}
 @Test void regenerateAdjustmentKeepsOriginalTaskIdentity()throws Exception{var dto=new TaskDTO();dto.setTitle("keep update identity");dto.setScheduledDate(LocalDate.now(ZoneId.of("Asia/Shanghai")));Long id=tasks.createTask(owner,dto);var first=plans.previewChanges(owner,request(90));var next=plans.regenerate(owner,first.planId(),request(60));assertEquals("UPDATE",next.action());assertEquals(id,next.tasks().get(0).existingTaskId());confirm(json.valueToTree(next),confirmation(json.valueToTree(next)));assertEquals(1,count());assertEquals(id,next.tasks().get(0).existingTaskId());}
 @Test void statusConfirmationCannotPretendToRenameTask()throws Exception{var dto=new TaskDTO();dto.setTitle("real status title");Long id=tasks.createTask(owner,dto);var d=plans.previewStatus(owner,id,"TASK",1,request(30));var r=confirmation(json.valueToTree(d));var i=d.tasks().get(0);r.setTasks(List.of(new PlanModels.EditedItem(i.key(),"fake renamed",1,i.priority())));assertEquals(400,assertThrows(com.knowflow.exception.BusinessException.class,()->plans.confirm(owner,d.planId(),r)).getCode());assertEquals("real status title",sql.queryForObject("SELECT title FROM task WHERE id=?",String.class,id));assertEquals(0,sql.queryForObject("SELECT status FROM task WHERE id=?",Integer.class,id));}

 @Test void todayIncludesUnfinishedOverdueTasksLikeExistingTaskCenter()throws Exception{var dto=new TaskDTO();dto.setTitle("overdue pending");dto.setScheduledDate(LocalDate.now(ZoneId.of("Asia/Shanghai")).minusDays(1));Long id=tasks.createTask(owner,dto);assertTrue(plans.todayTasks(owner,plans.normalize(request(60))).stream().anyMatch(t->id.equals(t.getId())));}

 @Test void completedHistoryCannotHideNewTaskFromLearningProjection()throws Exception{var d=plans.preview(owner,request(60));for(int i=0;i<100;i++)sql.update("INSERT INTO task(user_id,title,status,scheduled_date,learning_plan_ref,learning_metadata,deleted) VALUES(?,?,1,?,?,?,0)",owner,"old complete "+i,LocalDate.now().minusDays(2),d.planId(),plans.write(d.tasks().get(0)));var dto=new TaskDTO();dto.setTitle("new visible task");dto.setScheduledDate(LocalDate.now(ZoneId.of("Asia/Shanghai")));Long id=tasks.createTask(owner,dto);sql.update("UPDATE task SET learning_plan_ref=?,learning_metadata=? WHERE id=?",d.planId(),plans.write(d.tasks().get(0)),id);String body=http.perform(get("/api/learning/tasks").header("Authorization",auth(owner))).andExpect(status().isOk()).andReturn().getResponse().getContentAsString(java.nio.charset.StandardCharsets.UTF_8);assertTrue(json.readTree(body).path("data").toString().contains("new visible task"));}

 @Test void legacyStatusRollsBackWithoutManufacturingLearningEvents()throws Exception{sql.update("INSERT INTO learning_task(user_id,title,status,deleted) VALUES(?,?,0,0)",owner,"manual legacy");Long id=sql.queryForObject("SELECT id FROM learning_task WHERE user_id=?",Long.class,owner);var d=plans.previewStatus(owner,id,"LEARNING",1,request(60));doReturn(0).when(draftRows).updateById(any(LearningActionDraft.class));assertThrows(com.knowflow.exception.BusinessException.class,()->plans.confirm(owner,d.planId(),confirmation(json.valueToTree(d))));assertEquals(0,sql.queryForObject("SELECT status FROM learning_task WHERE id=?",Integer.class,id));assertEquals(0,sql.queryForObject("SELECT COUNT(*) FROM learning_event WHERE user_id=?",Integer.class,owner));}

 @Test void concurrentLegacyStatusDraftsConflictAndRecordOneActivityWithoutKnowledgeEvidence()throws Exception{sql.update("INSERT INTO learning_task(user_id,title,status,deleted) VALUES(?,?,0,0)",owner,"manual legacy concurrent");Long id=sql.queryForObject("SELECT id FROM learning_task WHERE user_id=?",Long.class,owner);var a=plans.previewStatus(owner,id,"LEARNING",1,request(60));var b=plans.previewStatus(owner,id,"LEARNING",1,request(60));var executor=Executors.newFixedThreadPool(2);try{var futures=executor.<Integer>invokeAll(List.of(()->{try{plans.confirm(owner,a.planId(),confirmation(json.valueToTree(a)));return 200;}catch(com.knowflow.exception.BusinessException ex){return ex.getCode();}},()->{try{plans.confirm(owner,b.planId(),confirmation(json.valueToTree(b)));return 200;}catch(com.knowflow.exception.BusinessException ex){return ex.getCode();}}));var results=futures.stream().map(f->{try{return f.get();}catch(Exception ex){throw new RuntimeException(ex);}}).sorted().toList();assertEquals(List.of(200,409),results);assertEquals(1,sql.queryForObject("SELECT status FROM learning_task WHERE id=?",Integer.class,id));// Phase G统一旧任务状态合同：确认成功只产生一条完成活动，仍不产生客观知识证据。
 assertEquals(1,sql.queryForObject("SELECT COUNT(*) FROM learning_event WHERE user_id=? AND event_type='LEARNING_TASK_COMPLETE' AND resource_type='TASK' AND resource_id=?",Integer.class,owner,id));assertEquals(0,sql.queryForObject("SELECT COUNT(*) FROM knowledge_mastery WHERE user_id=?",Integer.class,owner));assertEquals(0,sql.queryForObject("SELECT COUNT(*) FROM learning_task_evidence p JOIN task t ON t.id=p.task_id WHERE t.user_id=?",Integer.class,owner));}finally{executor.shutdownNow();}}

}
